/**
 * Delivery URLs for product videos stored on Cloudinary.
 *
 * Kept apart from cloudinaryImage.ts on purpose: that helper only ever
 * rewrites /image/upload/ URLs, and video delivery takes different
 * transformations.
 *
 *  - cloudinaryVideoUrl: adds f_auto,q_auto so each browser gets a format it
 *    can play. An iPhone .MOV (often HEVC) does not play in Chrome as stored;
 *    through f_auto Cloudinary hands Chrome an MP4/WebM instead.
 *  - cloudinaryVideoPoster: a JPG of the first frame, generated by Cloudinary
 *    from the video itself, so no separate poster upload is needed.
 *
 * Anything that is not an untransformed Cloudinary video upload is returned
 * unchanged (poster: '' — there is nothing to derive one from).
 */

const MARKER = '/video/upload/';
/** "f_auto,q_auto" style segment: comma-separated key_value parts. */
const TRANSFORM_SEGMENT = /^[a-z]{1,4}_[^/]*(,[a-z]{1,4}_[^/]*)*$/i;

function parse(url: string | undefined | null): { prefix: string; rest: string } | null {
  const trimmed = (url ?? '').trim();
  if (!trimmed) return null;
  let parsed: URL;
  try {
    parsed = new URL(trimmed);
  } catch {
    return null;
  }
  const host = parsed.hostname.toLowerCase();
  if (host !== 'res.cloudinary.com' && !host.endsWith('.res.cloudinary.com')) return null;
  const at = parsed.pathname.indexOf(MARKER);
  if (at < 0) return null;
  const rest = parsed.pathname.slice(at + MARKER.length);
  if (!rest || TRANSFORM_SEGMENT.test(rest.split('/')[0])) return null;
  return { prefix: `${parsed.origin}${parsed.pathname.slice(0, at + MARKER.length)}`, rest };
}

export function cloudinaryVideoUrl(url: string | undefined | null): string {
  const p = parse(url);
  return p ? `${p.prefix}f_auto,q_auto/${p.rest}` : (url ?? '');
}

export function cloudinaryVideoPoster(url: string | undefined | null, width = 600): string {
  const p = parse(url);
  if (!p) return '';
  const jpg = p.rest.replace(/\.[a-z0-9]+$/i, '') + '.jpg';
  return `${p.prefix}so_0,f_jpg,q_auto,w_${Math.round(width)},c_limit/${jpg}`;
}
